import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (x1**2 + (x2 - x1)**2 + (x3 - x2)**2 + 0.5*x1*x3) + 0.2*np.power(x1,3) + 0.1*x2 + np.sin(x1 + x2 + x3) + 0.5*np.exp(-(x1**2 + x2**2 + x3**2))

