import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (x1**2 + (x2 - x1)**2 + (x3 - x2)**2) + 0.2*np.power(x1,3) + 0.1*np.sin(x1 + x2 + x3) + 0.1*np.exp(-(x1**2 + x2**2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (x1**2 + x2**2 + x3**2 + 0.3*x1*x2) + 0.1*x1 + 0.2*x2 + 0.3*x3 + np.sin(x1 + x2) + 0.1*np.exp(-(x1**2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (x1**2 + (x2 - x1)**2 + (x3 - x2)**2 + 0.5*x1*x3) + 0.2*np.power(x1,3) + 0.1*x2 + np.sin(x1 + x2 + x3) + 0.5*np.exp(-(x1**2 + x2**2 + x3**2)) + 0.1 * np.exp(-((x1-1)**2 + (x2+1)**2 + (x3-0.5)**2)) * np.polynomial.chebyshev.chebval(x1 + x2 + x3, [0, 1, 0.5])

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (x1**2 + (x2 - x1)**2 + (x3 - x2)**2 + 0.5*x1*x3) + 0.1*x2 + np.sin(x1 * x2) + 0.5*np.exp(-(x1**2 + x2**2 + x3**2)) + 0.3*np.power(x1, 4)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (x1**2 + (x2 - x1)**2 + (x3 - x2)**2 + 0.5*x1*x3) + 0.2*np.power(x1,3) + 0.1*x2 + np.sin(x1 + x2 + x3) + 0.5*np.exp(-(x1**2 + x2**2 + x3**2)) + 0.3 * np.sqrt(np.abs(x1*x2) + np.abs(x2*x3))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (x1**2 + (x2 - x1)**2 + (x3 - x2)**2 + 0.5*x1*x3) + 0.2*np.power(x1,3) + 0.1*x2 + 0.05 * (x1**5 - 2*x2**3 + x3**2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (x1**2 + (x2 - x1)**2 + (x3 - x2)**2 + 0.5*x1*x3) + 0.2*np.power(x1,3) + 0.1*x2 + np.sin(x1 + x2 + x3) + 0.5*np.exp(-(x1**2 + x2**2 + x3**2)) + 0.1 * np.exp(-((x1-1)**2 + (x2+1)**2 + (x3-0.5)**2)) * np.polynomial.chebyshev.chebval(x1 + x2 + x3, [0, 1, 0.5]) + (x1**2)/(1 + x1**4)
